<?php require __DIR__.'/app/bootstrap.php';require_admin();$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='toggle_city'){$pdo->prepare('UPDATE municipalities SET is_enabled_for_reports=1-is_enabled_for_reports WHERE id=?')->execute([(int)$_POST['id']]);flash('success','Municipio actualizado.');redirect('admin.php#cities');}if($action==='verify_reviewer'){$pdo->prepare("UPDATE reviewer_profiles SET verification_status='verified' WHERE user_id=?")->execute([(int)$_POST['user_id']]);flash('success','Revisor verificado.');redirect('admin.php#reviewers');}}
$stats=$pdo->query("SELECT COUNT(*) reports, SUM(system_priority='urgent') urgent, SUM(status='pending') pending FROM damage_reports")->fetch();$reviewers=$pdo->query("SELECT u.id,u.name,u.email,rp.profession,rp.license_number,rp.organization_name,rp.verification_status FROM users u JOIN reviewer_profiles rp ON rp.user_id=u.id WHERE u.role='reviewer' ORDER BY u.created_at DESC LIMIT 50")->fetchAll();$cities=$pdo->query("SELECT m.id,m.name,m.is_enabled_for_reports,d.name department FROM municipalities m JOIN departments d ON d.id=m.department_id ORDER BY d.name,m.name LIMIT 300")->fetchAll();render_header('Administración');?>
<div class="container py-4"><h1>Administración</h1><div class="row g-3 mb-4"><div class="col-md-4"><div class="stat"><div class="fs-2 fw-bold"><?= (int)$stats['reports']?></div>Reportes</div></div><div class="col-md-4"><div class="stat"><div class="fs-2 fw-bold text-danger"><?= (int)$stats['urgent']?></div>Urgentes</div></div><div class="col-md-4"><div class="stat"><div class="fs-2 fw-bold"><?= (int)$stats['pending']?></div>Pendientes</div></div></div><h3 id="reviewers">Revisores</h3><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Nombre</th><th>Profesión</th><th>Organización</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($reviewers as $x):?><tr><td><?=e($x['name'])?><br><small><?=e($x['email'])?></small></td><td><?=e($x['profession'])?><br><small><?=e($x['license_number'])?></small></td><td><?=e($x['organization_name'])?></td><td><?=e(verification_label($x['verification_status']))?></td><td><?php if($x['verification_status']!=='verified'):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="verify_reviewer"><input type="hidden" name="user_id" value="<?=$x['id']?>"><button class="btn btn-sm btn-success">Verificar</button></form><?php endif?></td></tr><?php endforeach?></tbody></table></div><h3 id="cities" class="mt-5">Municipios habilitados</h3><p class="text-muted">Activa únicamente las ciudades donde se recibirán reportes.</p><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Departamento</th><th>Municipio</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($cities as $m):?><tr><td><?=e($m['department'])?></td><td><?=e($m['name'])?></td><td><?=$m['is_enabled_for_reports']?'Habilitado':'Deshabilitado'?></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="toggle_city"><input type="hidden" name="id" value="<?=$m['id']?>"><button class="btn btn-sm <?=$m['is_enabled_for_reports']?'btn-outline-danger':'btn-outline-success'?>"><?=$m['is_enabled_for_reports']?'Deshabilitar':'Habilitar'?></button></form></td></tr><?php endforeach?></tbody></table></div></div><?php render_footer();?>